from ux_channel.render.kit import attr_string, demo_button, demo_page, demo_scripts, script_tags
"""Raw main.py sources for create-app templates (substitute __TITLE__/__PORT__)."""

WEBRTC_MAIN = '"""\n__TITLE__ — WebRTC signaling scaffold (plugin only).\n\nChannel places scripts + data-* + client opts.\nYou own video/buttons/CSS (see examples/webrtc_ready).\n"""\n\nfrom __future__ import annotations\n\nimport json\n\nfrom fastapi import FastAPI\nfrom fastapi.responses import HTMLResponse\n\nfrom ux_channel import Channel\n\nfrom app.config import get_channel_config\n\napp = FastAPI(title="__TITLE__")\nch = Channel.boot(app, config=get_channel_config())\n\n\n@app.get("/health")\ndef health():\n    return {"ok": True, "template": "webrtc", "webrtc": ch.webrtc.diagnose()}\n\n\n@app.get("/", response_class=HTMLResponse)\ndef index():\n    p = ch.webrtc.plugin("lobby")\n    client = json.dumps(p.client)\n    # Minimal host shell — not a design system\n    return HTMLResponse(\n        f"""<!doctype html>\n<html lang="en"><head>\n<meta charset="utf-8"/>\n<meta name="viewport" content="width=device-width,initial-scale=1"/>\n<title>__TITLE__</title>\n{script_tags(p)}\n</head>\n<body {attr_string(p)}>\n  <h1>__TITLE__</h1>\n  <p>room <code>{p.room}</code> · signaling <code>{p.path}</code></p>\n  <p>Open two tabs. Build your UI; join with <code>UxWebRTC.join</code>.</p>\n  <pre id="opts">{client}</pre>\n  <script>\n    (function boot(n) {{\n      if (!window.UxWebRTC) {{\n        if (n > 80) return;\n        return setTimeout(function () {{ boot(n + 1); }}, 25);\n      }}\n      var opts = JSON.parse(document.getElementById("opts").textContent);\n      UxWebRTC.join(opts).then(function (room) {{\n        console.log("joined", room.peer);\n        window.__uxRtcRoom = room;\n      }});\n    }})(0);\n  </script>\n</body></html>\n"""\n    )\n\n\nif __name__ == "__main__":\n    import uvicorn\n\n    uvicorn.run("app.main:app", host="0.0.0.0", port=__PORT__, reload=True)\n'

FULL_MAIN = '"""\n__TITLE__ — full scaffold: live regions + WebRTC + health.\n\nKeep Channel.boot only in this module.\n"""\n\nfrom __future__ import annotations\n\nfrom fastapi import FastAPI\nfrom fastapi.responses import HTMLResponse\n\nfrom ux_channel import Channel\n\nfrom app.config import get_channel_config\n\napp = FastAPI(title="__TITLE__", version="0.1.0")\nch = Channel.boot(app, config=get_channel_config())\n\n\n@ch.region\ndef badge(ctx):\n    n = int(ch.draft.get("n", 0) or 0)\n    return f\'<span data-channel-id="badge">items {n}</span>\'\n\n\n@ch.on(refresh=[badge], idempotent=False)\ndef add_item():\n    ch.draft.set("n", int(ch.draft.get("n", 0) or 0) + 1)\n\n\n@app.get("/health")\ndef health():\n    return {"ok": True, "template": "full", "diagnose": ch.diagnose()}\n\n\n@app.get("/", response_class=HTMLResponse)\ndef index():\n    morph = demo_page(ch, \n        "<h2>Region morph</h2>",\n        badge,\n        demo_button(ch, "Add", add_item),\n        title="__TITLE__",\n        bridge=True,\n    )\n    link = f\'<p><a href="/call">Open WebRTC call</a> · rtc {ch.webrtc.path}</p>\'\n    text = str(morph)\n    if "</body>" in text:\n        return HTMLResponse(text.replace("</body>", link + "</body>"))\n    return HTMLResponse(text + link)\n\n\n@app.get("/call", response_class=HTMLResponse)\ndef call():\n    import json\n    p = ch.webrtc.plugin("full")\n    # Host-owned minimal shell (library does not ship call chrome)\n    return HTMLResponse(\n        f"""<!doctype html><html><head><meta charset="utf-8"/><title>Call</title>\n{script_tags(p)}</head>\n<body {attr_string(p)}>\n<h1>Call</h1>\n<video id="local" autoplay playsinline muted style="max-width:100%"></video>\n<button id="go" type="button">Start media</button>\n<pre id="log"></pre>\n<script>\nvar OPTS = {json.dumps(p.client)};\nvar log = function(t) {{ document.getElementById("log").textContent += t + "\\n"; }};\nvar room;\n(function boot(n) {{\n  if (!window.UxWebRTC) {{ if (n>80) return; return setTimeout(function(){{boot(n+1);}},25); }}\n  UxWebRTC.join(Object.assign({{}}, OPTS, {{\n    onLocalStream: function(s) {{ document.getElementById("local").srcObject = s; }},\n    onPeer: function(id, st) {{ log(id.slice(0,8)+" "+st); }},\n  }})).then(function(r) {{ room = r; log("joined"); }});\n}})(0);\ndocument.getElementById("go").onclick = function() {{\n  if (room) room.startMedia({{ audio: true, video: true }});\n}};\n</script>\n</body></html>"""\n    )\n\n\nif __name__ == "__main__":\n    import uvicorn\n\n    uvicorn.run("app.main:app", host="0.0.0.0", port=__PORT__, reload=True)\n'

MEDIA_MAIN = '"""\n__TITLE__ — media plane scaffold (ch.media.plugin).\n\nRun::\n\n    uvicorn app.main:app --host 0.0.0.0 --port __PORT__ --reload\n\nDX: ch.media.plugin places scripts + client bag; you own video tags.\n"""\n\nfrom __future__ import annotations\n\nfrom fastapi import FastAPI\nfrom fastapi.responses import HTMLResponse\n\nfrom ux_channel import Channel\n\nfrom app.config import get_channel_config\n\napp = FastAPI(title="__TITLE__", version="0.1.0")\nch = Channel.boot(app, config=get_channel_config())\n\n\n@app.get("/health")\ndef health():\n    return ch.doctor()\n\n\n@app.get("/", response_class=HTMLResponse)\ndef index():\n    p = ch.media.plugin("lobby", sub="demo-user")\n    client = p.client_json\n    style = (\n        "body{margin:0;padding:1.25rem;background:#0b0d12;color:#e8eaef;"\n        "font-family:system-ui,sans-serif}"\n        ".grid{display:grid;gap:1rem;grid-template-columns:1fr 1fr;max-width:960px}"\n        "video{width:100%;background:#000;border-radius:12px;aspect-ratio:4/3}"\n        ".badge{display:inline-block;padding:.2rem .5rem;border-radius:999px;"\n        "background:#1e293b;font-size:12px}pre{font-size:12px;opacity:.75}"\n    )\n    js = (\n        "(function(){"\n        "var opts=JSON.parse(document.getElementById(\'opts\').textContent);"\n        "if(opts.mode===\'sfu\'||opts.provider===\'livekit\'){console.log(\'sfu\',opts.room);return;}"\n        "function boot(n){"\n        "if(!window.UxWebRTC){if(n>80)return;return setTimeout(function(){boot(n+1);},25);}"\n        "UxWebRTC.join(Object.assign({},opts,{"\n        "onLocalStream:function(s){var el=document.querySelector(\'[data-channel-media-local]\');if(el)el.srcObject=s;},"\n        "onTrack:function(id,stream){var el=document.querySelector(\'[data-channel-media-remote]\');if(el)el.srcObject=stream;}"\n        "})).then(function(room){window.__uxRtcRoom=room;console.log(\'mesh\',room.peer);});"\n        "}"\n        "boot(0);"\n        "})();"\n    )\n    html = (\n        "<!doctype html><html lang=\'en\'><head>"\n        "<meta charset=\'utf-8\'/>"\n        "<title>__TITLE__</title>"\n        + script_tags(p)\n        + "<style>"\n        + style\n        + "</style></head><body "\n        + attr_string(p)\n        + "><h1>__TITLE__ <span class=\'badge\'>"\n        + p.mode\n        + " / "\n        + p.provider\n        + "</span></h1>"\n        "<p>Host-owned UI. Mesh: UxWebRTC. SFU: LiveKit when LIVEKIT_* set.</p>"\n        "<div class=\'grid\'>"\n        "<video data-channel-media-local autoplay playsinline muted></video>"\n        "<video data-channel-media-remote autoplay playsinline></video></div>"\n        "<pre id=\'opts\'>"\n        + client\n        + "</pre><script>"\n        + js\n        + "</script></body></html>"\n    )\n    return HTMLResponse(html)\n\n\nif __name__ == "__main__":\n    import uvicorn\n\n    uvicorn.run("app.main:app", host="0.0.0.0", port=__PORT__, reload=True)\n'
